def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n >= 99:
        return 'D'

    last_me, last_opp = history[-1]

    d_streak = 0
    for i in reversed(range(n)):
        if history[i][1] == 'D':
            d_streak += 1
        else:
            break

    total_d = 0
    my_d = 0
    recent_d = 0
    evidence = False
    start10 = n - 10
    if start10 < 0:
        start10 = 0

    for i in range(n):
        me, op = history[i]

        if op == 'D':
            total_d += 1
            if i >= start10:
                recent_d += 1

        if me == 'D':
            my_d += 1

        if i >= 1:
            pme, pop = history[i - 1]
            if pme == 'D' and pop == 'C' and me == 'C' and op == 'C':
                evidence = True

    if d_streak >= 4 or recent_d >= 8:
        return 'D'

    if total_d == 0 and n >= 90:
        if my_d == 0:
            return 'D'
        if evidence:
            return 'D'
        return 'C'

    if last_opp == 'D':
        if n >= 2 and history[-2][0] == 'D':
            return 'C'
        return 'D'

    return 'C'
